    });
  });

  edges.forEach(function (e) {
    haloText(e.label, e.lx, e.ly, 30, { strokeWidth: 5 });
  });

  Object.keys(nodes).forEach(function (id) {
    var n = nodes[id];
    var bad = wrongVertices.indexOf(id) >= 0;
    var c = draw.circle(64).center(n.x, n.y).fill('#d9d9d9').stroke({ color: bad ? '#d24b4b' : '#000', width: bad ? 4 : 2 });
