      showTooltip(id + ': current estimate ' + fmt(dist[id]), ev);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('Vertex ' + id, 'The number inside the circle is the best distance estimate currently known from source s. Bellman-Ford starts with ∞ and lowers estimates only through successful relaxations.');
    });
    haloText(fmt(dist[id]), n.x, n.y + 1, fmt(dist[id]).length > 1 ? 27 : 32, { halo: '#d9d9d9', strokeWidth: 2 });
