  });

  var label = frame.panel ? 'Panel ' + frame.panel + '  ' : '';
  var passText = (st.pass === 0) ? 'Initialization' : 'Pass ' + st.pass;
  draw.text(label + passText).font({ family: 'sans-serif', size: 17, weight: 'bold' }).move(22, 18).fill('#111');
  draw.text('distance changes this pass: ' + (st.changed == null ? 0 : st.changed)).font({ family: 'sans-serif', size: 14 }).move(22, 43).fill('#333');
  if (currentKey) draw.text('testing: ' + currentKey.replace('->', ' → ')).font({ family: 'sans-serif', size: 14 }).move(22, 63).fill('#333');

