        frames.push({ kind:'error', status:'error', state: cloneState(), currentEdge:null, message: 'Error: ' + (err && err.message ? err.message : err) });
        postMessage({ ok:false, frames, status:'error', error: err && err.message ? err.message : String(err) });
      }
    };
  `;
  var blob = new Blob([workerSource], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var done = false;
  var timeout = setTimeout(function () {
    if (done) return;
    done = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = [{ status: 'error', message: 'Error: timeout. The worker was stopped after about 2 seconds.', state: { pass: 0, changed: 0, dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, improvedThisPass: [] } }];
    document.getElementById('relaxCodeRun').disabled = false;
    document.getElementById('relaxCodeLog').value = frames[0].message;
    setStatus('error', '#b00020');
    showFrame(0);
  }, 1900);
  worker.onmessage = function (e) {
    if (done) return;
    done = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = e.data.frames || [];
    frameIndex = 0;
    document.getElementById('relaxCodeRun').disabled = false;
    var log = frames.map(function (f, i) { return (i + 1) + '. ' + (f.message || f.kind); }).join('\n');
    document.getElementById('relaxCodeLog').value = log;
    setStatus(e.data.status === 'correct' ? 'correct' : (e.data.status === 'wrong' ? 'wrong answer' : 'error'), e.data.status === 'correct' ? '#187a2f' : '#b00020');
    showFrame(0);
  };
  worker.onerror = function (err) {
    if (done) return;
    done = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = [{ status: 'error', message: 'Worker error: ' + err.message, state: { pass: 0, changed: 0, dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, improvedThisPass: [] } }];
    document.getElementById('relaxCodeRun').disabled = false;
    document.getElementById('relaxCodeLog').value = frames[0].message;
    setStatus('error', '#b00020');
    showFrame(0);
  };
  worker.postMessage({ code: code });
}

