  { panel: '(d)', dist: { s: 0, t: 2, x: 4, y: 7, z: 2 }, pred: { y: 's', x: 'y', t: 'x', z: 't' }, hi: ['s->y', 'y->x', 'x->t', 't->z'] },
  { panel: '(e)', dist: { s: 0, t: 2, x: 4, y: 7, z: -2 }, pred: { y: 's', x: 'y', t: 'x', z: 't' }, hi: ['s->y', 'y->x', 'x->t', 't->z'] }
];

var demoStep = 0;
var demoSteps = [
  { narration: 'The source s starts at distance 0; every other vertex displays ∞ because no path to it is known yet.' },
  { narration: 'The first successful relaxations leave s: edges s → t and s → y set estimates 6 and 7.' },
  { narration: 'Continuing the same edge order lets information propagate farther: y → x gives 4, and t → z gives 2.' },
  { narration: 'A negative edge can revise an old estimate. After x has distance 4, x → t lowers t from 6 to 2.' },
  { narration: 'One more pass lets the improved t relax t → z, lowering z to −2. Now the predecessor tree s → y → x → t → z is stable.' }
];

var frames = [];
var frameIndex = 0;
var playTimer = null;

function fmt(v) {
  return v === Infinity || v === 'Infinity' ? '∞' : String(v).replace('-', '−');
}
function keyOf(edge) {
  if (!edge) return null;
  return Array.isArray(edge) ? edge[0] + '->' + edge[1] : edge;
}
function makeMarker(color, size) {
  return draw.marker(size, size, function (add) {
    add.path('M 0 0 L ' + size + ' ' + (size / 2) + ' L 0 ' + size + ' z').fill(color).stroke('none');
  }).ref(size - 1, size / 2).orient('auto');
}
function addText(g, txt, x, y, size, opts) {
  opts = opts || {};
  var t = g.text(txt).font({
    family: opts.family || 'Georgia, Times New Roman, serif',
    size: size,
    anchor: 'middle',
