    weight: opts.weight || 'normal'
  }).fill(opts.fill || '#000').center(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: opts.halo || '#fff', 'stroke-width': opts.strokeWidth == null ? 3 : opts.strokeWidth, 'stroke-linejoin': 'round' });
  return t;
}
function predKeys(pred) {
  var out = [];
  Object.keys(pred || {}).forEach(function (v) {
    if (pred[v]) out.push(pred[v] + '->' + v);
  });
  return out;
}
function panelFromState(st) {
  var d = st && st.dist ? st.dist : {};
  if (d.z === -2) return '(e)';
  if (d.t === 2) return '(d)';
  if (d.x === 4 && d.z === 2) return '(c)';
  if (d.t === 6 && d.y === 7) return '(b)';
  return '(a)';
}
function drawEdgePath(g, e, color, width, opacity, marker) {
  return g.path(e.path).fill('none').stroke({ color: color, width: width, linecap: 'round', linejoin: 'round', opacity: opacity == null ? 1 : opacity }).marker('end', marker);
}
function drawOnePanel(x, y, scale, panel, opts) {
  opts = opts || {};
  var g = draw.group().translate(x, y).scale(scale);
  var blackArrow = opts.blackArrow || makeMarker('#000', 10);
  var grayArrow = opts.grayArrow || makeMarker('#b8b8b8', 18);
  var darkArrow = opts.darkArrow || makeMarker('#5f5f5f', 18);
  var redArrow = opts.redArrow || makeMarker('#c94a4a', 16);
  var dist = panel.dist || {};
  var pred = panel.pred || {};
  var hi = panel.hi || [];
  var currentKey = keyOf(panel.currentEdge);
  var wrongEdges = panel.wrongEdges || [];
  var wrongVertices = panel.wrongVertices || [];

  hi.forEach(function (k) {
    if (edgeByKey[k]) drawEdgePath(g, edgeByKey[k], '#b7b7b7', 14, 0.82, grayArrow);
  });
  if (currentKey && edgeByKey[currentKey]) drawEdgePath(g, edgeByKey[currentKey], '#5f5f5f', 18, 0.48, darkArrow);
  wrongEdges.forEach(function (k) {
    if (edgeByKey[k]) drawEdgePath(g, edgeByKey[k], '#c94a4a', 14, 0.45, redArrow);
  });

  localEdges.forEach(function (e) {
    var p = drawEdgePath(g, e, '#000', 1.8, 1, blackArrow);
    p.css('cursor', 'pointer').on('mousemove', function (ev) {
      showTooltip(e.u + ' → ' + e.v + ', weight ' + e.w, ev);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('Relax edge ' + e.u + ' → ' + e.v, 'Bellman-Ford tests whether dist(' + e.u + ') + ' + e.w + ' is smaller than dist(' + e.v + '). If so, the estimate for ' + e.v + ' and its predecessor are updated.');
    });
  });

  localEdges.forEach(function (e) {
    addText(g, e.label, e.lx, e.ly, 28, { strokeWidth: 4 });
  });

  Object.keys(localNodes).forEach(function (id) {
    var n = localNodes[id];
    var bad = wrongVertices.indexOf(id) >= 0;
    var c = g.circle(52).center(n.x, n.y).fill('#d9d9d9').stroke({ color: bad ? '#c94a4a' : '#000', width: bad ? 3.5 : 1.8 });
    c.css('cursor', 'pointer').on('mousemove', function (ev) {
      showTooltip(id + ': current estimate ' + fmt(dist[id]), ev);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('Vertex ' + id, 'The number inside the circle is the current best distance estimate from source s. Estimates start at ∞ and only decrease through successful relaxations.');
    });
    addText(g, fmt(dist[id]), n.x, n.y + 1, fmt(dist[id]).length > 1 ? 25 : 29, { halo: '#d9d9d9', strokeWidth: 1.6 });
    addText(g, id, n.lx, n.ly, 29, { style: 'italic', strokeWidth: 4 });
  });

  addText(g, panel.panel || panelFromState({ dist: dist }), 210, 345, 30, { strokeWidth: 4 });
  return g;
}
function drawAllPanels() {
  draw.clear();
  var positions = [
    [20, 18, 1.0],
    [545, 18, 1.0],
    [1070, 18, 1.0],
    [185, 455, 1.0],
    [710, 455, 1.0]
  ];
  for (var i = 0; i < sourcePanels.length; i++) {
    drawOnePanel(positions[i][0], positions[i][1], positions[i][2], sourcePanels[i], {});
  }
}
function frameToPanel(frame) {
  var st = frame && frame.state ? frame.state : { dist: sourcePanels[0].dist, pred: {} };
  var hi = [];
  if (st.improvedThisPass && st.improvedThisPass.length) hi = st.improvedThisPass.slice();
  else hi = predKeys(st.pred);
  return {
    panel: panelFromState(st),
    dist: st.dist || {},
    pred: st.pred || {},
    hi: hi,
    currentEdge: frame.currentEdge || (frame.indices && frame.indices.edge),
    wrongVertices: st.wrongVertices || [],
    wrongEdges: st.wrongEdges || []
  };
}
function drawReplayFrame(frame) {
  draw.clear();
  drawOnePanel(420, 115, 1.65, frameToPanel(frame), {});
}

function applyDemoStep(i) {
  stopPlay();
  demoStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  document.getElementById('demoNarration').textContent = demoSteps[demoStep].narration;
  document.getElementById('stepLabel').textContent = (demoStep + 1) + ' / ' + demoSteps.length;
  drawAllPanels();
}
function prevStep() { applyDemoStep(demoStep - 1); }
function nextStep() { applyDemoStep(demoStep + 1); }

function load_relaxCode_sample() { document.getElementById('relaxCodeCode').value = sampleCode; }
function load_relaxCode_buggy() { document.getElementById('relaxCodeCode').value = buggyCode; }
function load_relaxCode_starter() { document.getElementById('relaxCodeCode').value = starterCode; }

function setStatus(text, color) {
  var el = document.getElementById('relaxCodeStatus');
  el.textContent = text;
  el.style.color = color || '#333';
}
function showFrame(i) {
  if (!frames.length) return;
  frameIndex = Math.max(0, Math.min(frames.length - 1, i));
  var f = frames[frameIndex];
  drawReplayFrame(f);
  document.getElementById('frameCount').textContent = (frameIndex + 1) + ' of ' + frames.length;
  document.getElementById('frameCaption').textContent = f.message || '';
  if (frameIndex === frames.length - 1 && f.status) {
    if (f.status === 'correct') setStatus('correct', '#187a2f');
    else if (f.status === 'wrong') setStatus('wrong answer', '#b26a00');
    else setStatus('error', '#b00020');
  }
}
function firstFrame() { stopPlay(); showFrame(0); }
function prevFrame() { stopPlay(); showFrame(frameIndex - 1); }
function nextFrame() { stopPlay(); showFrame(frameIndex + 1); }
function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playBtn').textContent = 'Play';
}
function togglePlay() {
  if (!frames.length) return;
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playBtn').textContent = 'Pause';
  playTimer = setInterval(function () {
    if (frameIndex >= frames.length - 1) { stopPlay(); return; }
    showFrame(frameIndex + 1);
  }, 700 / (+document.getElementById('speedInput').value || 1));
}

function trigger_relaxCode() {
  stopPlay();
  setStatus('running...', '#555');
  document.getElementById('relaxCodeRun').disabled = true;
  document.getElementById('relaxCodeLog').value = '';
  var code = document.getElementById('relaxCodeCode').value;
  var workerSource = `
    const order = [
      ['s','t',6], ['s','y',7], ['t','x',5], ['t','y',8], ['t','z',-4],
      ['x','t',-2], ['y','x',-3], ['y','z',9], ['z','s',2], ['z','x',7]
    ];
    const vertices = ['s','t','x','y','z'];
    const expected = { s:0, t:2, x:4, y:7, z:-2 };
    const expectedPred = { y:'s', x:'y', t:'x', z:'t' };
    let distMap, predMap, pass, changed, currentEdge, improvedThisPass, frames, ops;
    function cloneState(extra) {
      const d = {};
      vertices.forEach(k => d[k] = distMap[k]);
      const p = {};
      Object.keys(predMap).forEach(k => p[k] = predMap[k]);
      return Object.assign({ pass, changed, dist:d, pred:p, improvedThisPass: improvedThisPass.slice() }, extra || {});
    }
    function val(v) { return v === Infinity ? '∞' : String(v); }
    function append(kind, indices, message, extraState) {
      ops++;
      if (ops > 2200) throw new Error('operation cap hit: the replay stopped after too many API calls');
      if (frames.length > 2600) throw new Error('frame cap hit: the replay became too long');
      frames.push({ kind, indices: indices || {}, currentEdge: currentEdge ? currentEdge.slice() : null, state: cloneState(extraState), message });
    }
    function checkVertex(v) {
      if (!vertices.includes(v)) throw new Error('unknown vertex "' + v + '"');
    }
    function dist(v) {
      checkVertex(v);
      append('dist', { vertices:[v], edge: currentEdge }, 'read dist(' + v + ') = ' + val(distMap[v]));
      return distMap[v];
    }
    function candidate(u, w) {
      checkVertex(u);
      if (typeof w !== 'number') throw new Error('candidate expects a numeric edge weight');
      const ans = distMap[u] === Infinity ? Infinity : distMap[u] + w;
      append('candidate', { vertices:[u], edge: currentEdge }, 'candidate through ' + u + ': ' + val(distMap[u]) + ' + ' + w + ' = ' + val(ans));
      return ans;
    }
    function less(a, b) {
      const ans = a < b;
      append('less', { edge: currentEdge }, 'compare ' + val(a) + ' < ' + val(b) + ' → ' + ans);
      return ans;
    }
    function setDist(v, value) {
      checkVertex(v);
      if (typeof value !== 'number') throw new Error('setDist expects a numeric value or Infinity');
      const old = distMap[v];
      distMap[v] = value;
      if (old !== value) {
        changed++;
        const k = currentEdge[0] + '->' + currentEdge[1];
        if (!improvedThisPass.includes(k)) improvedThisPass.push(k);
      }
      append('setDist', { vertices:[v], edge: currentEdge }, 'set dist(' + v + ') from ' + val(old) + ' to ' + val(value));
    }
    function setPred(v, u) {
      checkVertex(v); checkVertex(u);
      predMap[v] = u;
      append('setPred', { vertices:[u,v], edge: currentEdge }, 'set predecessor of ' + v + ' to ' + u);
    }
    function mark(u, v, note) {
      checkVertex(u); checkVertex(v);
      append('mark', { vertices:[u,v], edge:[u,v] }, 'mark ' + u + ' → ' + v + ': ' + (note || 'tested'));
    }
    onmessage = function(e) {
      frames = []; ops = 0;
      distMap = { s:0, t:Infinity, x:Infinity, y:Infinity, z:Infinity };
      predMap = {}; pass = 0; changed = 0; currentEdge = null; improvedThisPass = [];
      try {
        const factory = new Function('dist','candidate','less','setDist','setPred','mark', '"use strict";\\n' + e.data.code + '\\n; return (typeof relax === "function") ? relax : null;');
        const relax = factory(dist, candidate, less, setDist, setPred, mark);
        if (typeof relax !== 'function') throw new Error('missing entry point: define function relax(u, v, w)');
        append('init', {}, 'initialize s=0 and all other distances to ∞');
        for (pass = 1; pass <= 4; pass++) {
          changed = 0; improvedThisPass = []; currentEdge = null;
          append('pass', {}, 'start pass ' + pass + ' over the fixed edge order');
          for (const ed of order) {
            currentEdge = [ed[0], ed[1]];
            append('edge', { edge: currentEdge }, 'test edge ' + ed[0] + ' → ' + ed[1] + ' with weight ' + ed[2]);
            relax(ed[0], ed[1], ed[2]);
          }
          currentEdge = null;
          append('passEnd', {}, 'end pass ' + pass + ': ' + changed + ' distance change(s)');
        }
        const wrongVertices = [];
        Object.keys(expected).forEach(v => { if (distMap[v] !== expected[v]) wrongVertices.push(v); });
        Object.keys(expectedPred).forEach(v => { if (predMap[v] !== expectedPred[v] && !wrongVertices.includes(v)) wrongVertices.push(v); });
        const wrongEdges = [];
        for (const ed of order) {
          const alt = distMap[ed[0]] === Infinity ? Infinity : distMap[ed[0]] + ed[2];
          if (alt < distMap[ed[1]]) wrongEdges.push(ed[0] + '->' + ed[1]);
        }
        const ok = wrongVertices.length === 0 && wrongEdges.length === 0;
        frames.push({ kind:'final', status: ok ? 'correct' : 'wrong', state: cloneState({ wrongVertices, wrongEdges }), currentEdge:null, message: ok ? 'Correct: final distances are s=0, t=2, x=4, y=7, z=-2, and no edge can improve them.' : 'Wrong answer: red marks show incorrect vertices or edges that could still relax.' });
        postMessage({ ok:true, frames, status: ok ? 'correct' : 'wrong' });
      } catch (err) {
        frames.push({ kind:'error', status:'error', state: cloneState(), currentEdge:null, message: 'Error: ' + (err && err.message ? err.message : err) });
        postMessage({ ok:false, frames, status:'error', error: err && err.message ? err.message : String(err) });
      }
    };
  `;
  var blob = new Blob([workerSource], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var done = false;
  var timeout = setTimeout(function () {
    if (done) return;
    done = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = [{ status: 'error', message: 'Error: timeout. The worker was stopped after about 2 seconds.', state: { pass: 0, changed: 0, dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, improvedThisPass: [] } }];
    document.getElementById('relaxCodeRun').disabled = false;
    document.getElementById('relaxCodeLog').value = frames[0].message;
    setStatus('error', '#b00020');
    showFrame(0);
  }, 1900);
  worker.onmessage = function (e) {
    if (done) return;
    done = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = e.data.frames || [];
    frameIndex = 0;
    document.getElementById('relaxCodeRun').disabled = false;
    document.getElementById('relaxCodeLog').value = frames.map(function (f, i) { return (i + 1) + '. ' + (f.message || f.kind); }).join('\\n');
    setStatus(e.data.status === 'correct' ? 'correct' : (e.data.status === 'wrong' ? 'wrong answer' : 'error'), e.data.status === 'correct' ? '#187a2f' : (e.data.status === 'wrong' ? '#b26a00' : '#b00020'));
    showFrame(0);
  };
  worker.onerror = function (err) {
    if (done) return;
    done = true;
    clearTimeout(timeout);
    worker.terminate();
    URL.revokeObjectURL(url);
    frames = [{ status: 'error', message: 'Worker error: ' + err.message, state: { pass: 0, changed: 0, dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, improvedThisPass: [] } }];
    document.getElementById('relaxCodeRun').disabled = false;
    document.getElementById('relaxCodeLog').value = frames[0].message;
    setStatus('error', '#b00020');
    showFrame(0);
  };
  worker.postMessage({ code: code });
}

applyDemoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

